mapper.select:
SELECT ssr.SEQ_NO, ssr.ACCOUT busiAcctNo, ssr.SETTLE_DATE, ssr.FINPROD_ID, ssr.TRADE_MARKET, ssr.CHECK_RESULT, CASE
WHEN settle.FINPROD_TYPE2 IS NOT NULL THEN settle.FINPROD_TYPE2 WHEN ssrd.FINPROD_TYPE IS NOT NULL THEN ssrd.FINPROD_TYPE
WHEN ins.STOCK_CODE IS NOT NULL THEN #{prodType2_F07} WHEN fpt.TYPE_8 IS NOT NULL THEN fpt.TYPE_8 END FINPROD_TYPE, ssr.ENTRUST_TRADE_ID, ssr.CUSTOMER_ID, ssr.STL_SEC_DEME, ssrd.TRADE_ID, ssrd.SEAT_NUMBER, IFNULL(ssrd.COMMISSION_AMT,0) COMMISSION_AMT, IFNULL(ssrd.JSF_AMT,0) JSF_AMT, IFNULL(ssrd.ZGF_AMT,0) ZGF_AMT, IFNULL(ssrd.STAMP_FEE,0) STAMP_FEE, IFNULL(ssrd.SETTLE_FEE,0) SETTLE_FEE, IFNULL(ssrd.GHF_AMT,0) GHF_AMT, IFNULL(ssrd.SXF_AMT,0) SXF_AMT, IFNULL(ssrd.TRADE_AMT,0) TRADE_AMT, IFNULL(ssrd.TRADE_NUM,0) TRADE_NUM, ssrd.PS, ssrd.SEC_ACCT_ID, IFNULL(settle.COMMISSION_AMT,0) COMMISSION_AMT2, IFNULL(settle.JSF_AMT,0) JSF_AMT2, IFNULL(settle.ZGF_AMT,0) ZGF_AMT2, IFNULL(settle.STAMP_FEE,0) STAMP_FEE2, IFNULL(settle.SETTLE_FEE,0) SETTLE_FEE2, IFNULL(settle.GHF_AMT,0) GHF_AMT2, IFNULL(settle.SXF_AMT,0) SXF_AMT2, IFNULL(settle.FPRICE_AMT,0) TRADE_AMT2, IFNULL(settle.SHARE_AMT,0) TRADE_NUM2 FROM STL_SEC_RECON ssr LEFT JOIN STL_SEC_RECON_DEAL ssrd ON ssr.SEQ_NO = ssrd.SEQ_NO LEFT JOIN ( SELECT detail.SEQ_NO, std.FINPROD_TYPE2, SUM(std.COMMISSION_AMT) COMMISSION_AMT, SUM(std.JSF_AMT) JSF_AMT, SUM(std.ZGF_AMT) ZGF_AMT, SUM(std.STAMP_FEE) STAMP_FEE, SUM(std.SETTLE_FEE) SETTLE_FEE, SUM(std.GHF_AMT) GHF_AMT, SUM(std.SXF_AMT) SXF_AMT, SUM( CASE WHEN std.PS = #{PS_T01} AND std.FINPROD_TYPE2 != #{prodType2_F02} THEN std.FPRICE_AMT*-1 WHEN std.PS = #{PS_T56} AND std.BUSI_SCENE_CALSS = #{BUSI_SCENE_CALSS_0902RS03} AND std.TRADE_MARKET = #{TRADE_MARKET_03} THEN std.FPRICE_AMT*-1 WHEN std.PS = #{PS_T56} AND std.BUSI_SCENE_CALSS = #{BUSI_SCENE_CALSS_0902RB01} AND std.TRADE_MARKET = #{TRADE_MARKET_03} THEN std.FPRICE_AMT*-1 WHEN std.PS = #{PS_T56} AND std.BUSI_SCENE_CALSS = #{BUSI_SCENE_CALSS_0902RB04} AND std.TRADE_MARKET = #{TRADE_MARKET_03} THEN std.FPRICE_AMT*-1 WHEN std.PS IN (#{PS_T07},#{PS_T54},#{PS_T55},#{PS_T95},#{PS_T96}) AND std.FINPROD_TYPE2 = #{prodType2_F02} THEN std.FPRICE_AMT*-1 ELSE std.FPRICE_AMT END ) FPRICE_AMT, SUM( CASE WHEN std.PS = #{PS_T01} AND std.FINPROD_TYPE2 != #{prodType2_F02} THEN std.SHARE_AMT WHEN std.PS = #{PS_T56} AND std.BUSI_SCENE_CALSS = #{BUSI_SCENE_CALSS_0902RS03} THEN std.SHARE_AMT WHEN std.PS = #{PS_T56} AND std.BUSI_SCENE_CALSS = #{BUSI_SCENE_CALSS_0902RB01} THEN std.SHARE_AMT WHEN std.PS = #{PS_T56} AND std.BUSI_SCENE_CALSS = #{BUSI_SCENE_CALSS_0902RB04} THEN std.SHARE_AMT WHEN std.PS IN (#{PS_T07},#{PS_T54},#{PS_T55},#{PS_T95},#{PS_T96}) AND std.FINPROD_TYPE2 = #{prodType2_F02} THEN std.SHARE_AMT ELSE std.SHARE_AMT*-1 END ) SHARE_AMT FROM STL_SEC_RECON_DETAIL detail LEFT JOIN STL_SEC_RECON ssr1 ON detail.SEQ_NO = ssr1.SEQ_NO INNER JOIN SETTLE_TRANS_DATA std ON detail.TRADE_ID = std.TRADE_ID GROUP BY detail.SEQ_NO, std.FINPROD_TYPE2 )settle ON ssr.SEQ_NO = settle.SEQ_NO LEFT JOIN FIN_PRODUCT_TYPE fpt ON ssr.FINPROD_ID = fpt.FINPROD_ID LEFT JOIN T_INSTRUMENT ins ON ssr.FINPROD_ID = ins.STOCK_CODE WHERE 1=1
AND ssr.ACCOUT IN
#{item}
AND ssr.FINPROD_ID IN
#{item}
AND ssr.TRADE_MARKET = #{tradeMarket}
AND ssr.SETTLE_DATE >= STR_TO_DATE(#{tradeDateBegin}, '%Y-%m-%d')
AND ssr.SETTLE_DATE <= STR_TO_DATE(#{tradeDateEnd}, '%Y-%m-%d')
AND ssr.CHECK_RESULT = #{accountStatus}
ORDER BY CUSTOMER_ID,SETTLE_DATE DESC

with tmp as( select ssrd.SEQ_NO, ssrd.INSTRUCTION_ID, ssrd.PORTFOLIO_ID, ssrd.TRADE_DATE, ssrd.TRADE_ID, ssrd.FINPROD_ID, ssrd.MARKET_ID, ssrd.TRADE_MARKET, ssrd.CUSTOMER_ID, IFNULL(aa.PARA_VALUE, bb.PARA_VALUE) PARA_VALUE, ssrd.FINPROD_TYPE, ssrd.PS, ssrd.SEC_ACCT_ID, ssrd.COMMISSION_AMT, ssrd.JSF_AMT, ssrd.ZGF_AMT, ssrd.STAMP_FEE, ssrd.SETTLE_FEE, ssrd.GHF_AMT, ssrd.SXF_AMT, ssrd.TRADE_AMT, ssrd.TRADE_NUM from STL_SEC_RECON_DEAL ssrd left join STL_SEC_RECON ssr on ssr.SEQ_NO = ssrd.SEQ_NO left join STL_SEC_RECON_PARA aa on aa.CUSTOMER_ID = ssrd.CUSTOMER_ID and aa.PARA_CODE = #{PARA_CODE_02} left join STL_SEC_RECON_PARA bb on (bb.CUSTOMER_ID = '' or bb.CUSTOMER_ID is null) and bb.PARA_CODE = #{PARA_CODE_02} where (ssr.CHECK_RESULT IS NULL or ssr.CHECK_RESULT = '' or ssr.CHECK_RESULT = #{CHECK_RESULT_0}) and ssrd.TRADE_DATE = STR_TO_DATE(#{sysdate}, '%Y-%m-%d')
AND ssr.PORTFOLIO_ID IN
null) OR ssr.PORTFOLIO_ID IN (
#{item}
AND ssrd.FINPROD_ID like CONCAT_WS('', '%', #{finprodId}, '%')
AND ssrd.SEQ_NO = #{seqNo}
AND ssrd.TRADE_MARKET = #{tradeMarket}
) select a.SEQ_NO, a.INSTRUCTION_ID, a.PORTFOLIO_ID, a.TRADE_DATE, a.TRADE_ID, a.FINPROD_ID, a.MARKET_ID, a.TRADE_MARKET, a.CUSTOMER_ID, a.PARA_VALUE, a.FINPROD_TYPE, a.PS, a.SEC_ACCT_ID, a.COMMISSION_AMT, a.JSF_AMT, a.ZGF_AMT, a.STAMP_FEE, a.SETTLE_FEE, a.GHF_AMT, a.SXF_AMT, a.TRADE_AMT, a.TRADE_NUM, ss.APPLY_TRADE_ID TRADE_ID2, ss.COMMISSION_AMT2, ss.JSF_AMT2, ss.ZGF_AMT2, ss.STAMP_FEE2, ss.SETTLE_FEE2, ss.GHF_AMT2, ss.SXF_AMT2, ss.FPRICE_AMT2 TRADE_AMT2, ss.SHARE_AMT2 TRADE_NUM2, ss.FINPROD_TYPE2 FINPROD_TYPE2, ss.PS PS2, ss.TRADE_MARKET TRADE_MARKET2, ss.TRADE_DATE TRADE_DATE2, ss.SEC_ACCT_ID SEC_ACCT_ID2 from tmp a inner join ( select std.APPLY_TRADE_ID, SUM(std.COMMISSION_AMT) COMMISSION_AMT2, SUM(std.JSF_AMT) JSF_AMT2, SUM(std.ZGF_AMT) ZGF_AMT2, SUM(std.STAMP_FEE) STAMP_FEE2, SUM(std.SETTLE_FEE) SETTLE_FEE2, SUM(std.GHF_AMT) GHF_AMT2, SUM(std.SXF_AMT) SXF_AMT2, SUM(std.FPRICE_AMT) FPRICE_AMT2, SUM(std.SHARE_AMT) SHARE_AMT2, std.FINPROD_TYPE2, std.PS, std.TRADE_MARKET, std.TRADE_DATE, std.SEC_ACCT_ID from SETTLE_TRANS_DATA std inner join tmp b on b.INSTRUCTION_ID = std.APPLY_TRADE_ID and b.PARA_VALUE = #{PARA_VALUE_02} GROUP BY std.APPLY_TRADE_ID,std.FINPROD_TYPE2,std.PS,std.TRADE_MARKET,std.TRADE_DATE,std.SEC_ACCT_ID ) ss on a.INSTRUCTION_ID = ss.APPLY_TRADE_ID where a.PARA_VALUE = #{PARA_VALUE_02} UNION ALL select b.SEQ_NO, b.INSTRUCTION_ID, b.PORTFOLIO_ID, b.TRADE_DATE, b.TRADE_ID, b.FINPROD_ID, b.MARKET_ID, b.TRADE_MARKET, b.CUSTOMER_ID, b.PARA_VALUE, b.FINPROD_TYPE, b.PS, b.SEC_ACCT_ID, b.COMMISSION_AMT, b.JSF_AMT, b.ZGF_AMT, b.STAMP_FEE, b.SETTLE_FEE, b.GHF_AMT, b.SXF_AMT, b.TRADE_AMT, b.TRADE_NUM, std.TRADE_ID TRADE_ID2, std.COMMISSION_AMT COMMISSION_AMT2, std.JSF_AMT JSF_AMT2, std.ZGF_AMT ZGF_AMT2, std.STAMP_FEE STAMP_FEE2, std.SETTLE_FEE SETTLE_FEE2, std.GHF_AMT GHF_AMT2, std.SXF_AMT SXF_AMT2, std.FPRICE_AMT TRADE_AMT2, std.SHARE_AMT TRADE_NUM2, std.FINPROD_TYPE2 FINPROD_TYPE2, std.PS PS2, std.TRADE_MARKET TRADE_MARKET2, std.TRADE_DATE TRADE_DATE2, std.SEC_ACCT_ID SEC_ACCT_ID2 from SETTLE_TRANS_DATA std inner join tmp b on b.TRADE_ID = std.TRADE_ID and b.TRADE_ID is not null and b.TRADE_ID != '' and b.PARA_VALUE = #{PARA_VALUE_03} UNION ALL select b.SEQ_NO, b.INSTRUCTION_ID, b.PORTFOLIO_ID, b.TRADE_DATE, b.TRADE_ID, b.FINPROD_ID, b.MARKET_ID, b.TRADE_MARKET, b.CUSTOMER_ID, b.PARA_VALUE, b.FINPROD_TYPE, b.PS, b.SEC_ACCT_ID, b.COMMISSION_AMT, b.JSF_AMT, b.ZGF_AMT, b.STAMP_FEE, b.SETTLE_FEE, b.GHF_AMT, b.SXF_AMT, b.TRADE_AMT, b.TRADE_NUM, std.TRADE_ID TRADE_ID2, std.COMMISSION_AMT COMMISSION_AMT2, std.JSF_AMT JSF_AMT2, std.ZGF_AMT ZGF_AMT2, std.STAMP_FEE STAMP_FEE2, std.SETTLE_FEE SETTLE_FEE2, std.GHF_AMT GHF_AMT2, std.SXF_AMT SXF_AMT2, std.FPRICE_AMT TRADE_AMT2, std.SHARE_AMT TRADE_NUM2, std.FINPROD_TYPE2 FINPROD_TYPE2, std.PS PS2, std.TRADE_MARKET TRADE_MARKET2, std.TRADE_DATE TRADE_DATE2, std.SEC_ACCT_ID SEC_ACCT_ID2 from SETTLE_TRANS_DATA std inner join tmp b on b.PARA_VALUE = #{PARA_VALUE_03} and std.FINPROD_ID = b.FINPROD_ID and std.PS = b.PS and std.PORTFOLIO_ID = b.PORTFOLIO_ID and std.SEC_ACCT_ID = b.SEC_ACCT_ID and (b.TRADE_ID is null or b.TRADE_ID = '')

select
from settle_trans_data std WHERE 1=1
AND std.TRADE_ID = #{tradeId, jdbcType=VARCHAR}
AND std.APPLY_TRADE_ID = #{applyTradeId, jdbcType=VARCHAR}
order by std.SHARE_AMT desc

select std.TRADE_ID, std.CJBH,std.DEAL_DATE, std.SEC_TYPE, std.APPLY_TRADE_ID, std.FINPROD_ID, std.FINPROD_TYPE, std.FINPROD_TYPE2, std.BRANCH, BUSI_TYPE, std.TRADE_DATE, std.SETTLE_DATE, std.VDATE, std.MDATE, std.VPAY_DATE, std.MPAY_DATE, std.TERM_TYPE, std.SETTLE_SPEED, std.CCY, std.UNIT_CPRICE, std.UNIT_INT, std.UNIT_FPRICE, std.PAR_VALUE, std.CPRICE_AMT, std.SHARE_AMT, std.PRIN_AMT, std.INT_AMT, std.FPRICE_AMT, std.STAMP_FEE, std.JSF_AMT, std.GHF_AMT, std.ZGF_AMT, std.SXF_AMT, std.SETTLE_FEE, std.COMMISSION_AMT, std.IS_PAY_WITH_TRADE, std.TRADE_AMT, std.PS, std.TRADE_MARKET, std.TRADE_MARKET_MODE, std.TRADE_PLAT, std.PLEDGE_SEC_NUM, std.SEAT_NUMBER, std.PORTFOLIO_ID, std.SEC_ACCT_ID, std.ACCT_NO, std.BATCH_NUMBER, std.M_PRIN_AMT, std.M_INT_AMT, std.M_TRADE_AMT, std.INT_RATE, std.BASIS, std.BUSI_SCENE_CALSS, std.SETTLE_MODE, std.STAMP_FEE_RAW, std.JSF_AMT_RAW, std.GHF_AMT_RAW, std.ZGF_AMT_RAW, std.SXF_AMT_RAW, std.SETTLE_FEE_RAW, std.COMMISSION_AMT_RAW, std.TRADE_AMT_RAW, std.TRADE_ID_RAW, std.SEQ_NO, std.CREATE_USER, std.CREATE_DEPT, std.CREATE_TIME, std.UPDATE_USER, std.UPDATE_TIME, std.IS_PURCH_TYPE_YX from settle_trans_data std WHERE 1=1
AND std.FINPROD_ID = #{finprodId}
AND std.APPLY_TRADE_ID = #{entrustTradeId}
AND std.ACCT_NO = #{account}
AND std.SEAT_NUMBER = #{seatNumber}
AND std.TRADE_MARKET = #{tradeMarket}
AND std.DEAL_DATE = #{settleDate}

select table1.*,ifnull(table1.portfolioId,'null')||','||'1'||','||table1.busiAcctNo||','||DATE_FORMAT(table1.settleDate,'%Y-%m-%d')||','||table1.ccy childInfo from ( SELECT 'root' parentInfo, t1.CCY ccy, m2.CUSTOMER_NAME customerName, case when (SELECT count(distinct p.PORTFOLIO_ID) FROM PTL_CASH_POSITION p WHERE p.ACCT_ID = t1.ACCT_ID AND p.CCY = t1.CCY AND p.CDATE = t1.CDATE ) = 1 then ( SELECT distinct p.PORTFOLIO_ID FROM PTL_CASH_POSITION p WHERE p.ACCT_ID = t1.ACCT_ID AND p.CCY = t1.CCY AND p.CDATE = t1.CDATE ) else null end portfolioId, case when (SELECT count(distinct p.PORTFOLIO_ID) FROM PTL_CASH_POSITION p WHERE p.ACCT_ID = t1.ACCT_ID AND p.CCY = t1.CCY AND p.CDATE = t1.CDATE ) = 1 then ( SELECT DISTINCT p2.PORTFOLIO_NAME FROM PTL_CASH_POSITION p LEFT JOIN PTL_PORTFOLIO p2 ON p2.PORTFOLIO_ID = p.PORTFOLIO_ID WHERE p.ACCT_ID = t1.ACCT_ID AND p.CCY = t1.CCY AND p.CDATE = t1.CDATE ) else null end portfolioName, null secAcctId, s1.BUSI_ACCT_NO busiAcctNo, s1.ACCT_NAME acctName, t1.CDATE settleDate, null finprodId, null finprodName, null tradeMarket, 'F20' finprodType, t1.AMOUNT xiTongAmount, s2.ZYBS quanShangAmount, case when t1.AMOUNT = s2.ZYBS then '1' else '0' end checkResult FROM ( SELECT p1.ACCT_ID, p1.CDATE, p1.CCY, SUM(p1.AMOUNT) AMOUNT FROM PTL_CASH_POSITION p1 LEFT JOIN PTL_CAPACCT_INFO p2 ON p1.ACCT_ID = p2.ACCT_NO AND p1.PORTFOLIO_ID = p2.PORTFOLIO_ID AND p1.CCY = p2.CCY WHERE p2.ACCT_TYPE = 'A07' AND p1.HODING_TYPE = '03' GROUP BY p1.ACCT_ID, p1.CDATE, p1.CCY ) t1 LEFT JOIN STL_CAPACCT_INFO s1 ON t1.ACCT_ID = s1.ACCT_NO LEFT JOIN MST_SALE_DEPARTMENT m1 ON s1.OWN_DEPT = m1.SALE_DEPID LEFT JOIN MST_CUSTOMER_INFO m2 ON m1.BROKER_ID = m2.CUSTOMER_ID LEFT JOIN STL_CASH_RECON s2 ON t1.ACCT_ID = s2.ACCT_NO AND t1.CDATE = s2.CDATE AND t1.CCY = s2.JYLB
m2.CUSTOMER_ID = #{customerId}
AND t1.ACCT_ID IN
null) OR t1.ACCT_ID IN (
#{item}
AND case when t1.AMOUNT = s2.ZYBS then '1' else '0' end = #{accountStatus}
AND t1.CDATE>=STR_TO_DATE(#{tradeDateBegin},'%Y-%m-%d')
AND t1.CDATE<=STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
) table1
union all select table2.*,ifnull(table2.portfolioId,'null')||','||'2'||','||table2.finprodId||','||DATE_FORMAT(table2.settleDate,'%Y-%m-%d')||','||table2.secAcctId from ( SELECT 'root' parentInfo, null ccy, m2.CUSTOMER_NAME customerName, case when ( SELECT count(DISTINCT p1.PORTFOLIO_ID) FROM PTL_SEC_POSITION p1 WHERE p1.SEC_ACCT_ID=t1.SEC_ACCT_ID AND p1.FINPROD_ID=t1.FINPROD_ID AND p1.BRANCH='0' AND p1.CDATE=t1.CDATE )=1 then ( SELECT DISTINCT p1.PORTFOLIO_ID FROM PTL_SEC_POSITION p1 WHERE p1.SEC_ACCT_ID=t1.SEC_ACCT_ID AND p1.FINPROD_ID=t1.FINPROD_ID AND p1.BRANCH='0' AND p1.CDATE=t1.CDATE ) end portfolioId, case when ( SELECT count(DISTINCT p1.PORTFOLIO_ID) FROM PTL_SEC_POSITION p1 WHERE p1.SEC_ACCT_ID=t1.SEC_ACCT_ID AND p1.FINPROD_ID=t1.FINPROD_ID AND p1.BRANCH='0' AND p1.CDATE=t1.CDATE )=1 then ( SELECT DISTINCT p2.PORTFOLIO_NAME FROM PTL_SEC_POSITION p1 left join PTL_PORTFOLIO p2 on p2.PORTFOLIO_ID=p1.PORTFOLIO_ID WHERE p1.SEC_ACCT_ID=t1.SEC_ACCT_ID AND p1.FINPROD_ID=t1.FINPROD_ID AND p1.BRANCH='0' AND p1.CDATE=t1.CDATE ) end portfolioName, t1.SEC_ACCT_ID secAcctId, s2.BUSI_ACCT_NO busiAcctNo, s2.ACCT_NAME acctName, t1.CDATE settleDate, f1.FINPROD_ID finprodId, f1.FINPROD_NAME finprodName, f1.TRADE_MARKET tradeMarket, f2.TYPE_8 finprodType, t1.AMOUNT xiTongAmount, s3.AMOUT quanShangAmount, case when t1.AMOUNT = s3.AMOUT then '1' else '0' end checkResult FROM ( SELECT p1.FINPROD_ID,p1.SEC_ACCT_ID,p1.CDATE, SUM(p1.AMOUNT) AMOUNT FROM PTL_SEC_POSITION p1 LEFT JOIN STL_SEC_ACCT_INFO s1 ON p1.SEC_ACCT_ID=s1.SEC_ACCT_ID LEFT JOIN PTL_CAPACCT_INFO p2 ON s1.TRD_ACCT_ID=p2.ACCT_NO AND s1.TRD_ACCT_CCY=p2.CCY AND p1.PORTFOLIO_ID=p2.PORTFOLIO_ID
WHERE s1.SEC_ACCT_TYPE='SEC' AND s1.TRADE_PLACE IN ('03','04') AND p2.ACCT_TYPE='A07' AND p1.HODING_TYPE='03' AND p1.BRANCH='0' GROUP BY p1.FINPROD_ID,p1.SEC_ACCT_ID,p1.CDATE UNION ALL SELECT CASE WHEN f1.TERM_TYPE='GC001' THEN '204001' WHEN f1.TERM_TYPE='GC002' THEN '204002' WHEN f1.TERM_TYPE='GC003' THEN '204003' WHEN f1.TERM_TYPE='GC004' THEN '204004' WHEN f1.TERM_TYPE='GC007' THEN '204007' WHEN f1.TERM_TYPE='GC014' THEN '204014' WHEN f1.TERM_TYPE='GC028' THEN '204028' WHEN f1.TERM_TYPE='GC091' THEN '204091' WHEN f1.TERM_TYPE='GC182' THEN '204182' WHEN f1.TERM_TYPE='R-001' THEN '131810' WHEN f1.TERM_TYPE='R-002' THEN '131811' WHEN f1.TERM_TYPE='R-003' THEN '131800' WHEN f1.TERM_TYPE='R-007' THEN '131801' WHEN f1.TERM_TYPE='R-014' THEN '131802' WHEN f1.TERM_TYPE='R-028' THEN '131803' WHEN f1.TERM_TYPE='R-091' THEN '131805' WHEN f1.TERM_TYPE='R-128' THEN '131806' ELSE '131807' END FINPROD_ID, p1.SEC_ACCT_ID, p1.CDATE, SUM(p1.AMOUNT) AMOUNT FROM PTL_SEC_POSITION p1 LEFT JOIN STL_SEC_ACCT_INFO s1 ON p1.SEC_ACCT_ID=s1.SEC_ACCT_ID LEFT JOIN PTL_CAPACCT_INFO p2 ON s1.TRD_ACCT_ID=p2.ACCT_NO AND s1.TRD_ACCT_CCY=p2.CCY AND p1.PORTFOLIO_ID=p2.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT f1 ON p1.FINPROD_ID=f1.FINPROD_ID AND p1.BRANCH=f1.BRANCH WHERE s1.SEC_ACCT_TYPE='SEC' AND s1.TRADE_PLACE IN ('03','04') AND p2.ACCT_TYPE='A07' AND p1.HODING_TYPE='03' AND p1.BRANCH='0' GROUP BY f1.TERM_TYPE,p1.SEC_ACCT_ID,p1.CDATE ) t1 LEFT JOIN STL_SEC_ACCT_INFO s1 ON t1.SEC_ACCT_ID=s1.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO s2 ON s1.TRD_ACCT_ID=s2.BUSI_ACCT_NO AND s1.TRD_ACCT_CCY=s2.CCY LEFT JOIN MST_SALE_DEPARTMENT m1 ON s2.OWN_DEPT=m1.SALE_DEPID LEFT JOIN MST_CUSTOMER_INFO m2 ON m1.BROKER_ID=m2.CUSTOMER_ID LEFT JOIN STL_SECP_RECON s3 ON t1.SEC_ACCT_ID=s3.ACCT_NO AND t1.CDATE=s3.CDATE AND t1.FINPROD_ID=s3.FINPROD_ID LEFT JOIN FIN_PRODUCT f1 ON t1.FINPROD_ID=f1.FINPROD_ID left join FIN_PRODUCT_TYPE f2 on f1.FINPROD_ID=f2.FINPROD_ID
m2.CUSTOMER_ID = #{customerId}
AND t1.ACCT_ID IN
null) OR t1.ACCT_ID IN (
#{item}
AND case when t1.AMOUNT = s2.ZYBS then '1' else '0' end = #{accountStatus}
AND t1.CDATE>=STR_TO_DATE(#{tradeDateBegin},'%Y-%m-%d')
AND t1.CDATE<=STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
) table2
